def deep_dict_update(main_dict: Dict[Any, Any], update_dict: Dict[Any, Any]) -> None:
    """
    Recursively updates main_dict with the key-value pairs from update_dict.
    If a value in update_dict is a dictionary, it will recursively update the corresponding value in main_dict.
    """
    for key, value in update_dict.items():
        if isinstance(value, dict):
            if key in main_dict and isinstance(main_dict[key], dict):
                deep_dict_update(main_dict[key], value)
            else:
                main_dict[key] = value
        else:
            main_dict[key] = value
